{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "The existing disability-based eligibility route would require an active IEP listing one of 11 specified disabilities as the primary or secondary disability when the department receives the participation request",
      "rationale": "Conveys the active-IEP requirement, disability designation, and timing, but does not identify the qualifying disabilities or state that Tennessee residency also applies to this route."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "plus at least one of these conditions: the student attended a Tennessee public school for the full school year immediately before receiving an IEA, is enrolling in a Tennessee school for the first time, or received an IEA in the previous school year.",
      "rationale": "Conveys all three alternative enrollment/history conditions and their timing."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "The bill would expand eligibility for an individualized education account (IEA) to include a Tennessee resident child whose medical condition, as determined by the State Board of Education, prevents the child from attending school in person, if the child is entitled to attend public school.",
      "rationale": "Conveys the separate medical-condition route, residency, board determination, and public-school entitlement, but changes a condition that inhibits attendance to one that prevents attendance, narrowing the eligibility standard."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "For a student eligible because of a medical condition, a participating school could be a home school as defined in the cited law. The bill would make Section 49-10-1404 inapplicable to those students and their home schools, and would specify that references to participating schools in two other provisions apply to qualifying nonpublic schools, not home schools.",
      "rationale": "Conveys home-school participation for medically eligible students and recognizes qualifying nonpublic schools, but does not convey the nonpublic-school definition's requirement that the school seek to enroll eligible students."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The bill would make Section 49-10-1404 inapplicable to those students and their home schools",
      "rationale": "Identifies the exempted section and both the medically eligible students and their participating home schools."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "would specify that references to participating schools in two other provisions apply to qualifying nonpublic schools, not home schools.",
      "rationale": "Conveys the restriction to nonpublic schools but does not identify § 49-10-1403(d) and § 49-10-1405(a)(7). Those citations are material because the affected provisions are not otherwise identified."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "A parent of a medically eligible student would have to use IEA funds only for expenses approved under Section 49-10-1403(b).",
      "rationale": "Conveys the parent's responsibility, the medical-route scope, and the restriction to approved expenses under the specified provision."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "The department would have to regularly monitor those funds for compliance.",
      "rationale": "Conveys mandatory regular monitoring of medically eligible students' funds, but omits the express duty to create and implement a monitoring process and does not identify compliance with the new section as well as the approved-expense provision."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "It could suspend or terminate the student's participation if the parent failed to meet the spending requirement",
      "rationale": "Conveys the department's discretionary suspension or termination authority, but narrows the grounds from failure to comply with the new section's requirements to failure to meet the spending requirement."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "a student whose participation is terminated under this provision could not participate in the program again.",
      "rationale": "Conveys permanent future ineligibility following termination under the new provision."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2026.",
      "rationale": "States the exact effective date."
    }
  ]
}
